<details class="col-span-2 rounded-xl border border-leaf-200 bg-soil-50 px-3 py-2 text-soil-600 [&[open]>summary]:mb-2">
    <summary class="cursor-pointer select-none font-body text-xs font-medium text-soil-600 marker:text-leaf-400">
        Markdown cheat sheet
    </summary>

    <div class="grid grid-cols-1 gap-x-6 gap-y-1 font-mono text-xs sm:grid-cols-2">
        <div class="flex justify-between gap-3"><span class="text-soil-400"># Heading</span><span class="font-body font-semibold">Heading</span></div>
        <div class="flex justify-between gap-3"><span class="text-soil-400">**bold**</span><span class="font-body font-bold">bold</span></div>
        <div class="flex justify-between gap-3"><span class="text-soil-400">*italic*</span><span class="font-body italic">italic</span></div>
        <div class="flex justify-between gap-3"><span class="text-soil-400">~~strike~~</span><span class="font-body line-through">strike</span></div>
        <div class="flex justify-between gap-3"><span class="text-soil-400">[text](url)</span><span class="font-body text-leaf-600 underline">link</span></div>
        <div class="flex justify-between gap-3"><span class="text-soil-400">`code`</span><span class="rounded bg-leaf-100 px-1 font-mono">code</span></div>
        <div class="flex justify-between gap-3"><span class="text-soil-400">- item</span><span class="font-body">bullet list</span></div>
        <div class="flex justify-between gap-3"><span class="text-soil-400">1. item</span><span class="font-body">numbered list</span></div>
        <div class="flex justify-between gap-3"><span class="text-soil-400">- [ ] task</span><span class="font-body">checklist</span></div>
        <div class="flex justify-between gap-3"><span class="text-soil-400">&gt; quote</span><span class="font-body italic">blockquote</span></div>
        <div class="flex justify-between gap-3"><span class="text-soil-400">---</span><span class="font-body">divider</span></div>
        <div class="flex justify-between gap-3"><span class="text-soil-400">| a | b |</span><span class="font-body">table</span></div>
    </div>
</details>
